import re
import json

class Counter:
  def __init__(self):
    self.counts = {}

  def count_words(self, text):
    words = re.findall(r'\b\w+\b', text)
    for word in words:
      self.counts[word] = self.counts.get(word, 0) + 1

  def dump(self):
    json_str = json.dumps({'counts': self.counts}, indent=2)
    with open('counts.txt', 'w', encoding='utf-8') as f:
      f.write(json_str)

counts = Counter()
